                        {<<"tensorloom.shapes::type::Matrix">>, []},
                        Schema,
                        Symbols,
                        [],
                        [
                            finite_literal_1(Symbols),
                            finite_literal_2(Symbols),
                            finite_literal_3(Symbols),
                            finite_literal_4(Symbols),
                            finite_literal_5(Symbols),
                            finite_literal_6(Symbols),
                            finite_literal_7(Symbols),
                            finite_literal_8(Symbols),
                            finite_literal_9(Symbols)
                        ],
                        none
                    ),
                    fun(Argument0) ->
                        'Elixir.LawSpec.Beam.StreamData':bind(
                            'Elixir.LawSpec.Beam.StreamData':refine_input(
                                'Elixir.LawSpec.Beam.StreamData':generator(
                                    {<<"BigUInt">>, []},
                                    Schema,
                                    Symbols,
                                    [{<<"<=">>, 4}],
                                    [0, 1, 340282366920938463463374607431768211456],
                                    none
                                ),
                                fun(Argument1) -> (Argument1 =< 4) end
                            ),
                            fun(Argument1) ->
                                'Elixir.LawSpec.Beam.StreamData':exactly([Argument0, Argument1])
                            end
                        )
                    end
                )
            ),
            fun(Values) -> law_contract_sliceshape(Schema, Symbols, Values) end
        ),
        [{numtests, 50}, {constraint_tries, 10000}, {max_shrinks, 1000}]
    ).

finite_literal_shape_1(_Symbols, Fields) ->
    {ls_data, <<"tensorloom.shapes::type::Matrix::Matrix">>, Fields}.

finite_literal_1(Symbols) -> finite_literal_shape_1(Symbols, [0, 0]).

finite_literal_2(Symbols) -> finite_literal_shape_1(Symbols, [1, 1]).

finite_literal_3(Symbols) -> finite_literal_shape_1(Symbols, [4, 4]).

finite_literal_4(Symbols) -> finite_literal_shape_1(Symbols, [0, 1]).

finite_literal_5(Symbols) -> finite_literal_shape_1(Symbols, [0, 4]).

finite_literal_6(Symbols) -> finite_literal_shape_1(Symbols, [1, 0]).

finite_literal_7(Symbols) -> finite_literal_shape_1(Symbols, [1, 4]).

finite_literal_8(Symbols) -> finite_literal_shape_1(Symbols, [4, 0]).

finite_literal_9(Symbols) -> finite_literal_shape_1(Symbols, [4, 1]).

type_big_u_int() -> {<<"BigUInt">>, []}.

type_bool() -> {<<"Bool">>, []}.

type_integer() -> {<<"Integer">>, []}.

type_list_big_u_int() -> {<<"List">>, [{<<"BigUInt">>, []}]}.

type_matrix() -> {<<"tensorloom.shapes::type::Matrix">>, []}.

make_cons(Fields, Schema) ->
    lawspec_beam_schema:construct(<<"List::Cons">>, Fields, type_list_big_u_int(), Schema).

make_nil(Fields, Schema) ->
    lawspec_beam_schema:construct(<<"List::Nil">>, Fields, type_list_big_u_int(), Schema).

make_matrix(Fields, Schema) ->
    lawspec_beam_schema:construct(
        <<"tensorloom.shapes::type::Matrix::Matrix">>,
        Fields,
        type_matrix(),
        Schema
    ).
